package io.github.diodeme.ji.artifact;

import java.util.Arrays;

/** Small direct upload command; workspace source paths are deliberately absent. */
public record DirectUpload(ArtifactScope scope, String mediaType, String displayName, byte[] bytes) {
    public DirectUpload {
        if (scope == null) throw new IllegalArgumentException("scope is required");
        if (mediaType == null || mediaType.isBlank()) throw new IllegalArgumentException("mediaType must not be blank");
        if (displayName == null || displayName.isBlank()) throw new IllegalArgumentException("displayName must not be blank");
        bytes = Arrays.copyOf(bytes, bytes.length);
    }

    @Override public byte[] bytes() { return Arrays.copyOf(bytes, bytes.length); }
}
